def gen(rng):
    def fmt(iv):
        return str(len(iv)) + '\n' + '\n'.join(f'{a} {b}' for a, b in iv)
    tests = [fmt([(0, 5), (1, 2), (2, 3), (4, 8), (7, 9)]), fmt([(1, 2), (1, 2), (1, 2)]), fmt([(1, 2), (2, 3), (3, 4)]),
             fmt([(1, 2)]), fmt([(-10**9, 10**9), (-5, 5), (0, 1)]), fmt([(1, 100), (2, 3), (4, 5), (6, 7)]),
             fmt([(1, 3), (2, 4)]), fmt([(-5, -3), (-4, -2), (-3, -1)])]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            iv = []
            for _ in range(n):
                a = rng.randint(-15, 15)
                iv.append((a, a + rng.randint(1, 8)))
            tests.append(fmt(iv))
    def rnd(n, span, maxlen):
        iv = []
        for _ in range(n):
            a = rng.randint(-span, span - 1)
            iv.append((a, min(span, a + rng.randint(1, maxlen))))
        return iv
    tests.append(fmt(rnd(100000, 10**9, 10**4)))
    tests.append(fmt(rnd(100000, 10**9, 10**9)))
    tests.append(fmt(rnd(100000, 200000, 5)))
    tests.append(fmt([(-10**9 + i, 10**9 - i) for i in range(100000)]))
    tests.append(fmt([(i, i + 1) for i in range(100000)]))
    return tests
